/**
 * @file sit_reminder_main.cpp
 * @brief 久坐提醒系统 - ESP32-S3 Eye
 *
 * 功能：
 * 1. 使用 esp-who 检测人脸
 * 2. 检测同一人脸在画面中超过30分钟
 * 3. 触发 LED 灯光提醒
 * 4. 通过 WiFi 向电脑推送通知
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "freertos/event_groups.h"
#include "esp_log.h"
#include "esp_camera.h"
#include "esp_err.h"
#include "esp_wifi.h"
#include "esp_event.h"
#include "esp_netif.h"
#include "nvs_flash.h"
#include "esp_http_client.h"
#include "driver/gpio.h"
#include "driver/ledc.h"

// ESP32-S3 Eye 摄像头引脚定义
#define CAM_PIN_PWDN    -1
#define CAM_PIN_RESET   -1
#define CAM_PIN_XCLK    15
#define CAM_PIN_SIOD    4
#define CAM_PIN_SIOC    5
#define CAM_PIN_D7      16
#define CAM_PIN_D6      17
#define CAM_PIN_D5      18
#define CAM_PIN_D4      12
#define CAM_PIN_D3      10
#define CAM_PIN_D2      8
#define CAM_PIN_D1      9
#define CAM_PIN_D0      11
#define CAM_PIN_VSYNC   6
#define CAM_PIN_HREF    7
#define CAM_PIN_PCLK    13

// LED 引脚定义 (ESP32-S3 Eye)
#define LED_GPIO        48      // 板载 RGB LED
#define LED_RED_GPIO    47      // 红色 LED (如果有)
#define LED_GREEN_GPIO  48      // 绿色 LED
#define LED_BLUE_GPIO   46      // 蓝色 LED

// WiFi 配置 (需要修改为你的网络)
#define WIFI_SSID       "YOUR_WIFI_SSID"
#define WIFI_PASS       "YOUR_WIFI_PASSWORD"
#define SERVER_URL      "http://192.168.1.100:8080/notify"  // 电脑 IP 和端口

// 久坐提醒配置
#define SIT_THRESHOLD_MINUTES   30      // 久坐阈值（分钟）
#define CHECK_INTERVAL_MS       1000    // 检测间隔（毫秒）
#define FACE_ABSENT_TIMEOUT_MS  5000    // 人脸消失后重置计时（毫秒）

static const char *TAG = "sit_reminder";

// WiFi 事件组
static EventGroupHandle_t s_wifi_event_group;
#define WIFI_CONNECTED_BIT BIT0
#define WIFI_FAIL_BIT      BIT1

// 人脸检测状态
typedef struct {
    bool face_detected;             // 当前是否检测到人脸
    time_t first_detect_time;       // 首次检测时间
    time_t last_detect_time;        // 最后检测时间
    bool reminder_triggered;        // 是否已触发提醒
    uint32_t consecutive_seconds;   // 连续检测秒数
} face_state_t;

static face_state_t face_state = {
    .face_detected = false,
    .first_detect_time = 0,
    .last_detect_time = 0,
    .reminder_triggered = false,
    .consecutive_seconds = 0
};

// WiFi 事件处理
static void wifi_event_handler(void* arg, esp_event_base_t event_base,
                              int32_t event_id, void* event_data)
{
    if (event_base == WIFI_EVENT && event_id == WIFI_EVENT_STA_START) {
        esp_wifi_connect();
    } else if (event_base == WIFI_EVENT && event_id == WIFI_EVENT_STA_DISCONNECTED) {
        esp_wifi_connect();
        xEventGroupClearBits(s_wifi_event_group, WIFI_CONNECTED_BIT);
    } else if (event_base == IP_EVENT && event_id == IP_EVENT_STA_GOT_IP) {
        ip_event_got_ip_t* event = (ip_event_got_ip_t*) event_data;
        ESP_LOGI(TAG, "Connected! IP: " IPSTR, IP2STR(&event->ip_info.ip));
        xEventGroupSetBits(s_wifi_event_group, WIFI_CONNECTED_BIT);
    }
}

// 初始化 WiFi
static void wifi_init(void)
{
    s_wifi_event_group = xEventGroupCreate();

    esp_netif_init();
    esp_event_loop_create_default();
    esp_netif_create_default_wifi_sta();

    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
    esp_wifi_init(&cfg);

    esp_event_handler_instance_t instance_any_id;
    esp_event_handler_instance_t instance_got_ip;
    esp_event_handler_instance_register(WIFI_EVENT, ESP_EVENT_ANY_ID, &wifi_event_handler, NULL, &instance_any_id);
    esp_event_handler_instance_register(IP_EVENT, IP_EVENT_STA_GOT_IP, &wifi_event_handler, NULL, &instance_got_ip);

    wifi_config_t wifi_config = {
        .sta = {
            .ssid = WIFI_SSID,
            .password = WIFI_PASS,
        },
    };
    esp_wifi_set_mode(WIFI_MODE_STA);
    esp_wifi_set_config(WIFI_IF_STA, &wifi_config);
    esp_wifi_start();

    ESP_LOGI(TAG, "WiFi initialized");
}

// 初始化摄像头
static esp_err_t init_camera(void)
{
    camera_config_t config;
    config.ledc_channel = LEDC_CHANNEL_0;
    config.ledc_timer = LEDC_TIMER_0;
    config.pin_d0 = CAM_PIN_D0;
    config.pin_d1 = CAM_PIN_D1;
    config.pin_d2 = CAM_PIN_D2;
    config.pin_d3 = CAM_PIN_D3;
    config.pin_d4 = CAM_PIN_D4;
    config.pin_d5 = CAM_PIN_D5;
    config.pin_d6 = CAM_PIN_D6;
    config.pin_d7 = CAM_PIN_D7;
    config.pin_xclk = CAM_PIN_XCLK;
    config.pin_pclk = CAM_PIN_PCLK;
    config.pin_vsync = CAM_PIN_VSYNC;
    config.pin_href = CAM_PIN_HREF;
    config.pin_sccb_sda = CAM_PIN_SIOD;
    config.pin_sccb_scl = CAM_PIN_SIOC;
    config.pin_pwdn = CAM_PIN_PWDN;
    config.pin_reset = CAM_PIN_RESET;
    config.xclk_freq_hz = 20000000;
    config.pixel_format = PIXFORMAT_RGB565;
    config.frame_size = FRAMESIZE_QVGA;
    config.jpeg_quality = 12;
    config.fb_count = 2;
    config.grab_mode = CAMERA_GRAB_WHEN_EMPTY;
    config.fb_location = CAMERA_FB_IN_PSRAM;

    esp_err_t err = esp_camera_init(&config);
    if (err != ESP_OK) {
        ESP_LOGE(TAG, "Camera init failed: 0x%x", err);
        return err;
    }

    // 设置摄像头参数
    sensor_t *s = esp_camera_sensor_get();
    if (s) {
        s->set_vflip(s, 0);
        s->set_hmirror(s, 1);
        s->set_brightness(s, 1);
    }

    ESP_LOGI(TAG, "Camera initialized");
    return ESP_OK;
}

// 初始化 LED
static void init_led(void)
{
    // 配置 LED GPIO
    gpio_config_t io_conf = {
        .pin_bit_mask = (1ULL << LED_GPIO),
        .mode = GPIO_MODE_OUTPUT,
        .pull_up_en = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type = GPIO_INTR_DISABLE,
    };
    gpio_config(&io_conf);

    // 使用 LEDC 控制 RGB LED (如果支持 PWM)
    ledc_timer_config_t ledc_timer = {
        .speed_mode = LEDC_LOW_SPEED_MODE,
        .timer_num = LEDC_TIMER_1,
        .duty_resolution = LEDC_TIMER_8_BIT,
        .freq_hz = 5000,
        .clk_cfg = LEDC_AUTO_CLK,
    };
    ledc_timer_config(&ledc_timer);

    ledc_channel_config_t ledc_channel = {
        .speed_mode = LEDC_LOW_SPEED_MODE,
        .channel = LEDC_CHANNEL_1,
        .timer_sel = LEDC_TIMER_1,
        .gpio_num = LED_GPIO,
        .duty = 0,
        .hpoint = 0,
    };
    ledc_channel_config(&ledc_channel);

    ESP_LOGI(TAG, "LED initialized");
}

// 设置 LED 状态
static void set_led(bool on, uint8_t brightness)
{
    if (on) {
        ledc_set_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL_1, brightness);
        ledc_update_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL_1);
    } else {
        ledc_set_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL_1, 0);
        ledc_update_duty(LEDC_LOW_SPEED_MODE, LEDC_CHANNEL_1);
    }
}

// LED 呼吸灯效果
static void led_breathe_effect(void *pvParameters)
{
    ESP_LOGI(TAG, "LED breathe effect started");

    while (1) {
        // 渐亮
        for (int duty = 0; duty < 256; duty += 5) {
            set_led(true, duty);
            vTaskDelay(pdMS_TO_TICKS(20));
        }
        // 渐暗
        for (int duty = 255; duty >= 0; duty -= 5) {
            set_led(true, duty);
            vTaskDelay(pdMS_TO_TICKS(20));
        }
    }
}

// 发送 HTTP 通知到电脑
static void send_notification(const char *message)
{
    // 检查 WiFi 是否连接
    EventBits_t bits = xEventGroupGetBits(s_wifi_event_group);
    if (!(bits & WIFI_CONNECTED_BIT)) {
        ESP_LOGW(TAG, "WiFi not connected, cannot send notification");
        return;
    }

    esp_http_client_config_t config = {
        .url = SERVER_URL,
        .method = HTTP_METHOD_POST,
    };

    esp_http_client_handle_t client = esp_http_client_init(&config);

    // 设置 POST 数据
    char post_data[256];
    snprintf(post_data, sizeof(post_data),
             "{\"message\":\"%s\",\"timestamp\":%ld}",
             message, (long)time(NULL));

    esp_http_client_set_header(client, "Content-Type", "application/json");
    esp_http_client_set_post_field(client, post_data, strlen(post_data));

    esp_err_t err = esp_http_client_perform(client);
    if (err == ESP_OK) {
        ESP_LOGI(TAG, "Notification sent! Status: %d",
                 esp_http_client_get_status_code(client));
    } else {
        ESP_LOGE(TAG, "Failed to send notification: %s", esp_err_to_name(err));
    }

    esp_http_client_cleanup(client);
}

// 人脸检测任务 (使用 esp-who)
static void face_detection_task(void *pvParameters)
{
    ESP_LOGI(TAG, "Face detection task started");

    // 注意：这里需要集成 esp-who 的人脸检测
    // 以下是伪代码，实际需要使用 esp-who API

    while (1) {
        // 获取摄像头帧
        camera_fb_t *fb = esp_camera_fb_get();
        if (!fb) {
            ESP_LOGE(TAG, "Camera capture failed");
            vTaskDelay(pdMS_TO_TICKS(100));
            continue;
        }

        // TODO: 使用 esp-who 进行人脸检测
        // 例如：
        // auto detect = new WhoDetect("face_detect", frame_cap->get_last_node());
        // detect->set_detect_result_cb([](const WhoDetect::result_t &result) {
        //     face_state.face_detected = !result.det_res.empty();
        // });

        // 临时实现：模拟人脸检测（实际应替换为 esp-who）
        // 这里只是示例，实际代码需要集成 esp-who
        ESP_LOGI(TAG, "Frame captured: %dx%d", fb->width, fb->height);

        // 释放帧缓冲区
        esp_camera_fb_return(fb);

        vTaskDelay(pdMS_TO_TICKS(CHECK_INTERVAL_MS));
    }
}

// 久坐检测任务
static void sit_detection_task(void *pvParameters)
{
    ESP_LOGI(TAG, "Sit detection task started");

    // LED 呼吸灯任务句柄
    TaskHandle_t led_task_handle = NULL;

    while (1) {
        time_t current_time = time(NULL);

        if (face_state.face_detected) {
            // 检测到人脸
            if (face_state.first_detect_time == 0) {
                // 首次检测
                face_state.first_detect_time = current_time;
                face_state.last_detect_time = current_time;
                face_state.consecutive_seconds = 0;
                face_state.reminder_triggered = false;
                ESP_LOGI(TAG, "Face first detected");
            } else {
                // 连续检测
                face_state.last_detect_time = current_time;
                face_state.consecutive_seconds = (uint32_t)difftime(current_time, face_state.first_detect_time);

                ESP_LOGI(TAG, "Face detected for %lu seconds", (unsigned long)face_state.consecutive_seconds);

                // 检查是否超过阈值
                if (face_state.consecutive_seconds >= SIT_THRESHOLD_MINUTES * 60) {
                    if (!face_state.reminder_triggered) {
                        // 触发久坐提醒
                        ESP_LOGW(TAG, "SIT REMINDER TRIGGERED! %lu minutes",
                                 (unsigned long)(face_state.consecutive_seconds / 60));

                        face_state.reminder_triggered = true;

                        // 启动 LED 呼吸灯效果
                        if (led_task_handle == NULL) {
                            xTaskCreatePinnedToCore(
                                led_breathe_effect,
                                "led_breathe",
                                2048,
                                NULL,
                                5,
                                &led_task_handle,
                                0
                            );
                        }

                        // 发送通知到电脑
                        send_notification("久坐提醒：您已连续坐了30分钟，请起来活动一下！");

                        // 等待一段时间后重置
                        vTaskDelay(pdMS_TO_TICKS(60000));  // 等待1分钟
                        face_state.reminder_triggered = false;
                        face_state.first_detect_time = current_time;

                        // 停止 LED 效果
                        if (led_task_handle != NULL) {
                            vTaskDelete(led_task_handle);
                            led_task_handle = NULL;
                            set_led(false, 0);
                        }
                    }
                }
            }
        } else {
            // 未检测到人脸
            if (face_state.first_detect_time != 0) {
                // 检查是否超时（人脸离开画面）
                time_t absent_time = difftime(current_time, face_state.last_detect_time);
                if (absent_time * 1000 >= FACE_ABSENT_TIMEOUT_MS) {
                    // 重置计时器
                    ESP_LOGI(TAG, "Face absent for %ld seconds, resetting timer", (long)absent_time);
                    face_state.first_detect_time = 0;
                    face_state.last_detect_time = 0;
                    face_state.consecutive_seconds = 0;
                    face_state.reminder_triggered = false;

                    // 停止 LED 效果
                    if (led_task_handle != NULL) {
                        vTaskDelete(led_task_handle);
                        led_task_handle = NULL;
                        set_led(false, 0);
                    }
                }
            }
        }

        vTaskDelay(pdMS_TO_TICKS(1000));  // 每秒检查一次
    }
}

// 主函数
extern "C" void app_main(void)
{
    ESP_LOGI(TAG, "=== 久坐提醒系统启动 ===");

    // 初始化 NVS
    esp_err_t ret = nvs_flash_init();
    if (ret == ESP_ERR_NVS_NO_FREE_PAGES || ret == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_ERROR_CHECK(nvs_flash_erase());
        ret = nvs_flash_init();
    }
    ESP_ERROR_CHECK(ret);

    // 初始化 WiFi
    wifi_init();

    // 初始化摄像头
    ret = init_camera();
    if (ret != ESP_OK) {
        ESP_LOGE(TAG, "Camera init failed!");
        return;
    }

    // 初始化 LED
    init_led();

    // 创建人脸检测任务（核心 0）
    xTaskCreatePinnedToCore(
        face_detection_task,
        "face_detect",
        8192,
        NULL,
        5,
        NULL,
        0
    );

    // 创建久坐检测任务（核心 1）
    xTaskCreatePinnedToCore(
        sit_detection_task,
        "sit_detect",
        4096,
        NULL,
        5,
        NULL,
        1
    );

    ESP_LOGI(TAG, "System ready! Waiting for face detection...");
}
